namespace HybridCPU_ISE.Tests.Architecture;
public sealed class Rf129adLane7VirtualTokenAuthorityDecisionTests
{[Fact] public void PaperKeepsNativeHandleOutsideGuestVirtualState(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("For a Lane-7 virtual token handle",p,StringComparison.Ordinal);Assert.Contains("zero/default is unissued or absent",p,StringComparison.Ordinal);Assert.Contains("must not expose, reconstruct or substitute",p,StringComparison.Ordinal);Assert.Contains("No generic token conversion",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
